.sc-tw :root{
            color-scheme: dark;
            --bg: #050505;
            --panel: rgba(255, 255, 255, 0.03);
            --panel-strong: rgba(255, 255, 255, 0.05);
            --line: rgba(255, 255, 255, 0.08);
            --line-strong: rgba(255, 255, 255, 0.14);
            --muted: rgba(255, 255, 255, 0.58);
            --muted-2: rgba(255, 255, 255, 0.36);
            --soft: rgba(255, 255, 255, 0.02);
            --accent: oklch(0.78 0.02 260);
            --accent-soft: oklch(0.72 0.01 260 / 0.12);
        }.sc-tw *{
            box-sizing: border-box;
        }.sc-tw html{
            scroll-behavior: smooth;
        }.sc-tw{
            margin: 0;
            font-family: "Inter", sans-serif;
            color: white;
            background:
                radial-gradient(circle at 50% 0%, rgba(255, 255, 255, 0.07), transparent 24%),
                radial-gradient(circle at 80% 15%, rgba(255, 255, 255, 0.04), transparent 22%),
                radial-gradient(circle at 15% 80%, rgba(255, 255, 255, 0.03), transparent 25%),
                linear-gradient(180deg, #090909 0%, #050505 48%, #020202 100%);
            overflow-x: hidden;
        }.sc-tw body::before{
            content: "";
            position: fixed;
            inset: 0;
            pointer-events: none;
            background-image:
                linear-gradient(rgba(255, 255, 255, 0.028) 1px, transparent 1px),
                linear-gradient(90deg, rgba(255, 255, 255, 0.028) 1px, transparent 1px);
            background-size: 88px 88px;
            mask-image: radial-gradient(circle at center, black 36%, transparent 90%);
            opacity: 0.55;
            z-index: -2;
        }.sc-tw .mono{
            font-family: "JetBrains Mono", monospace;
        }.sc-tw .glass{
            background: linear-gradient(180deg, rgba(255, 255, 255, 0.045), rgba(255, 255, 255, 0.02));
            border: 1px solid rgba(255, 255, 255, 0.08);
            backdrop-filter: blur(26px) saturate(1.15);
            -webkit-backdrop-filter: blur(26px) saturate(1.15);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, 0.045),
                0 18px 80px rgba(0, 0, 0, 0.45);
        }.sc-tw .glass-strong{
            background: linear-gradient(180deg, rgba(255, 255, 255, 0.06), rgba(255, 255, 255, 0.03));
            border: 1px solid rgba(255, 255, 255, 0.1);
            backdrop-filter: blur(30px) saturate(1.2);
            -webkit-backdrop-filter: blur(30px) saturate(1.2);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, 0.05),
                0 22px 90px rgba(0, 0, 0, 0.48);
        }.sc-tw .soft-ring{
            position: relative;
        }.sc-tw .soft-ring::before{
            content: "";
            position: absolute;
            inset: -1px;
            border-radius: inherit;
            padding: 1px;
            background: linear-gradient(135deg, rgba(255, 255, 255, 0.12), rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.1));
            -webkit-mask: linear-gradient(#000 0 0) content-box, linear-gradient(#000 0 0);
            -webkit-mask-composite: xor;
            mask-composite: exclude;
            pointer-events: none;
        }.sc-tw .hover-lift{
            transition:
                transform 520ms cubic-bezier(.16, 1, .3, 1),
                border-color 240ms ease,
                background 240ms ease,
                box-shadow 240ms ease;
            will-change: transform;
        }.sc-tw .hover-lift:hover{
            transform: translateY(-6px);
            border-color: rgba(255, 255, 255, 0.18);
            background: rgba(255, 255, 255, 0.045);
            box-shadow:
                inset 0 1px 0 rgba(255, 255, 255, 0.05),
                0 30px 90px rgba(0, 0, 0, 0.55),
                0 0 0 1px rgba(255, 255, 255, 0.04);
        }.sc-tw .sheen{
            position: relative;
            overflow: hidden;
        }.sc-tw .sheen::after{
            content: "";
            position: absolute;
            inset: -120%;
            background: linear-gradient(120deg, transparent 43%, rgba(255, 255, 255, 0.16) 49%, transparent 56%);
            transform: translateX(-140%) rotate(10deg);
            animation: sheen 7s ease-in-out infinite;
            pointer-events: none;
            mix-blend-mode: screen;
        }.sc-tw .aurora{
            position: absolute;
            inset: auto;
            width: 34rem;
            height: 34rem;
            filter: blur(70px);
            opacity: 0.95;
            pointer-events: none;
        }.sc-tw .aurora.one{
            top: -12rem;
            left: 50%;
            transform: translateX(-50%);
            background: radial-gradient(circle, rgba(255, 255, 255, 0.10), transparent 60%);
        }.sc-tw .aurora.two{
            top: 10rem;
            right: -8rem;
            background: radial-gradient(circle, rgba(255, 255, 255, 0.05), transparent 60%);
        }.sc-tw .title{
            letter-spacing: -0.085em;
            line-height: 0.9;
        }.sc-tw .fade-up{
            opacity: 0;
            transform: translateY(24px);
            animation: fadeUp 0.88s cubic-bezier(.16, 1, .3, 1) forwards;
            animation-timeline: view();
            animation-range: entry 8% cover 28%;
        }.sc-tw .fade-soft{
            opacity: 0;
            transform: translateY(14px);
            animation: fadeSoft 0.8s cubic-bezier(.16, 1, .3, 1) forwards;
            animation-timeline: view();
            animation-range: entry 10% cover 24%;
        }.sc-tw .floaty{
            animation: floaty 10s ease-in-out infinite;
        }.sc-tw .progress{
            transform-origin: left;
            animation: progress linear both;
            animation-timeline: scroll(root);
        }.sc-tw .typed{
            display: inline-block;
            position: relative;
        }.sc-tw .typed::after{
            content: "";
            position: absolute;
            right: -0.35em;
            top: 10%;
            width: 1px;
            height: 82%;
            background: rgba(255, 255, 255, 0.7);
            animation: blink 1s steps(2, end) infinite;
        }.sc-tw .chip{
            background: rgba(255, 255, 255, 0.03);
            border: 1px solid rgba(255, 255, 255, 0.08);
        }.sc-tw .stat-divider{
            position: relative;
        }.sc-tw .stat-divider::before{
            content: "";
            position: absolute;
            left: 0;
            top: 0;
            width: 1px;
            height: 100%;
            background: linear-gradient(to bottom, transparent, rgba(255, 255, 255, 0.14), transparent);
        }.sc-tw .accent{
            color: #e7c57a;
        }.sc-tw .accent-bg{
            background: rgba(255, 255, 255, 0.045);
        }.sc-tw .portal-mask{
            -webkit-mask-image: radial-gradient(circle at center, black 18%, transparent 72%);
            mask-image: radial-gradient(circle at center, black 18%, transparent 72%);
        }.sc-tw #portal-container,.sc-tw #portal-video{
            will-change: transform;
            transform-origin: center center;
        }.sc-tw #portal-video{
            transform: scale(2);
        }

        @keyframes fadeUp {to{
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes fadeSoft {to{
                opacity: 1;
                transform: translateY(0);
            }
        }

        @keyframes sheen {to{
                transform: translateX(240%) rotate(10deg);
            }
        }

        @keyframes floaty {0%,100%{
                transform: translateY(0);
            }50%{
                transform: translateY(-12px);
            }
        }

        @keyframes blink {50%{
                opacity: 0;
            }
        }

        @keyframes progress {from{
                transform: scaleX(0);
            }to{
                transform: scaleX(1);
            }
        }.sc-tw ::view-transition-old(root),.sc-tw ::view-transition-new(root){
            animation-duration: 0.65s;
            animation-timing-function: cubic-bezier(.16, 1, .3, 1);
